INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(13, 'Junior IT Recruiting Consultant', 'Intercon Solutions GmbH', 'We are a recruitment agency with a successful history from Düsseldorf, specializing in the placement of IT and ERP specialists. Our goal is to connect companies with the talents that really make a difference. We achieve this every day! Now you\'re in the game! We are looking for a motivated Junior IT Recruiting Consultant who has 1-3 years of experience in 180° recruiting and now aims to enter 360° recruiting. Ideally, you have already worked in IT recruiting and have sales experience. Your tasks will include: building your role in 360° recruiting, customer care, candidate development, identification and approach of skilled workers through various recruiting channels, conducting interviews, and accompanying candidates throughout the process. You will also be responsible for market observation in the IT sector, demand determination, customer communication, and process coordination. As you gain experience, you will take over customer acquisition, contract negotiations, and process management. Qualifications: 1-3 years of experience in 180° recruiting in the IT field or in sales and/or sales. Knowledge or initial specialization in IT recruiting. Strong communication and advisory skills.', '[\"Remote\",\"HR\"]', 'Cologne', 1, NULL, 'arbeitnow', 'https://www.arbeitnow.com/jobs/companies/intercon-solutions-gmbh/zielstrebiger-junior-it-recruiting-consultant-gesucht-100-remote-innerhaln-der-brd-cologne-357549', 'zielstrebiger-junior-it-recruiting-consultant-gesucht-100-remote-innerhaln-der-brd-cologne-357549', '[-0.0073026,0.016794275,0.024412079,-0.054913707,0.004027979,0.030396465,0.0012013454,0.014360575,-0.009728409,-0.00042620828,-0.00050647673,0.0054798177,-0.0014264488,-0.0024930474,0.10128348,0.030699413,0.01660143,0.009384552,-0.016082995,-0.010971634,-0.020445868,0.0081458725,-0.003633122,-0.013545949,-0.010314392,-0.0476807,-0.011138895,0.008847349,0.010779549,0.02712877,-0.0023617428,0.033044893