INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(186, 'Enterprise Risk Management Specialist, Luxembourg', 'Stripe', '<p><strong>Position Overview:</strong> Bridge Building S.A. (BBSA) is building a Luxembourg regulated EMI and CASP. We are seeking an Enterprise Risk Management (ERM) Specialist to build and operate BBSA’s enterprise risk framework across financial and non-financial risks, ensuring clear governance, effective risk assessments, and inspection-ready documentation. The role supports senior management and the Board with actionable risk reporting and disciplined issue remediation.</p>\n<p><strong>Key Responsibilities:</strong></p>\n<ol>\n<li><strong>ERM Framework and Governance:</strong></li>\n<ul>\n<li>Implement and maintain BBSA’s ERM framework, including risk taxonomy, risk appetite statements, risk register, and escalation processes.</li>\n<li>Coordinate risk governance forums and prepare management and Board risk reporting packs (KRIs/KPIs, trends, and key decisions).</li>\n</ul>\n<li><strong>Risk and Control Assessments:</strong></li>\n<ul>\n<li>Facilitate periodic risk and control assessments across BBSA functions (Operations, Treasury, Compliance/AML, ICT, Outsourcing).</li>\n<li>Support business change and new product risk assessments, ensuring risks are identified, mitigated, and documented.</li>\n</ul>\n<li><strong>Issue, Incident, and Remediation Management:</strong></li>\n<ul>\n<li>Operate the issue management lifecycle: logging, root cause analysis, action plans, tracking, and validation of closure.</li>\n<li>Partner with InfoSec and Compliance on operational incidents, control weaknesses, and regulatory findings.</li>\n</ul>\n<li><strong>Third Party and Outsourcing Risk:</strong></li>\n<ul>\n<li>Support outsourcing risk oversight, including concentration risk considerations, critical provider monitoring, and exit planning in collaboration with the Outsourcing function.</li>\n<li>Ensure third party risk is consistently assessed and reported within the ERM framework.</li>\n</ul>\n<li><strong>Risk Culture and Continuous Improvement:</strong></li>\n<ul>\n<li>Contribute to risk policies, procedures, and training; 
