INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(265, 'IT Governance, Risk & Compliance (GRC) Analyst, Luxembourg', 'Stripe', '<h3><strong>Secure and Scale a Regulated Fintech Platform at the Heart of Stripe</strong></h3>\n<p><strong>Bridge Building S.A. (BBSA)</strong> is the Luxembourg regulated entity of <strong>Bridge</strong>, a Stripe company. We operate as an EMI and future CASP in one of Europe’s most demanding regulatory environments (CSSF, DORA, MiCA).</p>\n<p>BBSA is building a local regulated platform powered by a global-first technology model. In this context, we are looking for a sharp <strong>IT GRC Analyst</strong> to act as the bridge between strict European regulations and high-velocity global engineering.</p>\n<p>This role is the <strong>control and risk right hand</strong> of the Luxembourg Head of IT. While our global teams build the tech, you ensure it is compliant, resilient, and audit-ready. You will translate requirements like <strong>DORA</strong> and <strong>MiCA</strong> into tangible IT controls, oversee third-party risks, and maintain the integrity of our governance framework.</p>\n<p>This is not a \"tick-the-box\" compliance role. It is a operational position for a professional who understands technology well enough to govern it effectively. You will have high visibility, owning the frameworks that allow us to scale securely.</p>\n<h3><strong>Key Responsibilities</strong></h3>\n<ol>\n<li><strong> IT Governance &amp; 
INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
