INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(270, 'Legal Counsel, EMEA Marketing', 'Stripe', '<h2><strong>Who we are </strong></h2>\n<h3><strong>About Stripe</strong></h3>\n<p><span style=\"font-weight: 400;
INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(271, 'Legal Entity Controller', 'Stripe', '<p>Stripe’s mission is to increase the GDP of the internet. We build the most powerful and flexible tools for running an internet business. We handle billions of dollars each year and enable millions of users around the world to scale faster and more efficiently by building their businesses on Stripe.</p>\n<p>To further this important mission, we are building our International Accounting Stripe Delivery Center team and are looking for someone to help us scale for the future in a fast paced environment.</p>\n<p><strong>You Will</strong></p>\n<ul>\n<li>Perform month end accounting processes to support rapid global growth</li>\n<li>Work in three main pillars financial close and analysis, audit and regulatory compliance and reporting</li>\n<li>Own the Statutory Financial Statement preparation, Audit, review and sign off and adoption of financial statements with the board of directors. </li>\n<li>Work with Local service providers to ensure compliance and filing requirements are met timely and accurately. </li>\n<li>Work with cross functional partners like Tax, Treasury, Accounting and other groups to ensure that financial results of the legal entities remain compliant with US Gaap and Local Gaaps. </li>\n<li>Perform monthly and quarterly close activities, including manual journal entries, balance sheet reconciliations, variance analyses and analytical reviews, producing internal management reporting and external audit support</li>\n<li>Potential to perform month end activities and grow into other task and process to take on further responsibilities</li>\n<li>Be responsible for end to end preparation of journal entries and balance sheet reconciliations</li>\n<li>Prepare flux analysis and potential commentary and explanation on movements and trends</li>\n<li>Be responsible for performing transactional based work and streamlining processes</li>\n<li>Be a self starter and seek to standardize and centralize tasks </li>\n<li>Own problems not just processes or projects - we want our specialists to own the full problem space and do what it takes to solve them</li>\n<li>Partner with multiple cross-functional stakeholders and subject matter experts to develop and improve controllership processes and to anticipate changing business requirements</li>\n<li>Scale our financial processes through automation and standardization </li>\n</ul>\n<p><strong>We Are Looking For Someone Who Has</strong></p>\n<ul>\n<li>An accountancy qualification (e.g CA, ACA, ACCA, CIMA) with 8+ years of relevant accounting experience</li>\n<li>Degree in Accounting or Finance background</li>\n<li>Proven experience in the monthly close process, journal preparation and posting, audit, and exposure to accounting systems.</li>\n<li>Experience in month end reporting and analytics</li>\n<li>Working knowledge of US GAAP </li>\n<li>The ability to bring structure to ambiguous areas of opportunity and thrive in an unstructured, fast-moving environment</li>\n<li>Strong analytical skills and strong knowledge of Excel.</li>\n<li>Knowledge of data modeling or experience in any analytics tool will be an added advantage.</li>\n<li>An enthusiastic “roll up your sleeves” mentality</li>\n<li>A passion for creating new systems and solving problems via infrastructure and automation</li>\n<li>Demonstrated ability to work cross-functionally and with different cultures</li>\n<li>Demonstrated experience with internal controls</li>\n<li>Ability to be flexible and comfortable with changing requirements</li>\n</ul>\n<p><strong>Nice to haves</strong></p>\n<ul>\n<li>Knowledge of (or experience in) the technology or payments industry</li>\n<li>Oracle suite</li>\n<li>Hubble/SQL</li>\n</ul>\n<p> </p>', '[\"SQL\",\"Excel\",\"Accounting\",\"GAAP\"]', 'Bangalore', 0, 'Full-time', 'greenhouse', 'https://stripe.com/jobs/search?gh_jid=6209187', '6209187', '[-0.009062032,0.011334403,0.017305,-0.06241444,-0.008706906,-0.009522684,0.006589828,0.009110062,0.00024336597,0