INSERT IGNORE INTO `Job` (`id`, `title`, `company`, `description`, `tags`, `location`, `remote`, `jobType`, `sourceApi`, `sourceUrl`, `externalId`, `embedding`, `embeddedAt`, `postedAt`, `createdAt`, `updatedAt`, `category`) VALUES
(424, 'Security Engineer, Bridge', 'Stripe', '<h2><strong>Who we are </strong></h2>\n<h3><strong>About Bridge</strong></h3>\n<p>Bridge is Stripe’s fintech innovation hub focused on building a modern, stablecoin-powered cross-border payments network. We operate like a startup within Stripe: fast-paced, entrepreneurial, and product-obsessed, but with the backing of one of the most trusted names in fintech.</p>\n<p>We’re hiring a<strong> Security Engineer</strong> to build and scale Bridge’s security foundation. This is a rare opportunity to design a security program from the ground up, while also leveraging the infrastructure, best practices, and tooling of one of the most mature security organizations in the industry.</p>\n<h2><strong>What you’ll do</strong></h2>\n<h3><strong>Responsibilities</strong></h3>\n<ul>\n<li>Design, and implement Bridge’s security roadmap from first principles to production.</li>\n<li>Identify and tackle Bridge’s most important security risks quickly and pragmatically.</li>\n<li>Integrate with Stripe’s infrastructure where it makes sense, and find custom solutions where it doesn’t.</li>\n<li>Lead threat modeling and hardening efforts for Bridge’s money movement systems in collaboration with crypto and infra teams.</li>\n<li>Build key security capabilities (monitoring, secrets management, incident response, access controls, CI/CD hardening, etc).</li>\n<li>Reinforce engineering best practices around secure development and infrastructure.</li>\n<li>Ensure Bridge meets compliance and audit expectations as we scale to more regulated markets.</li>\n<li>Collaborate cross-functionally with engineering, product, and Stripe’s security org to move fast without compromising safety.</li>\n</ul>\n<h2><strong>About you</strong></h2>\n<p>You might be a good fit if you:</p>\n<ul>\n<li>Have 8+ years of experience in Security engineering, ideally with time spent in fast-paced startup environments where you’ve built security practices from the ground up.</li>\n<li>Have a startup mindset: you’re scrappy, pragmatic, and move quickly to solve the most critical problems.</li>\n<li>Are comfortable writing and debugging backend application code (Ruby is a plus, but not required).</li>\n<li>Thrive in ambiguity and know how to ruthlessly prioritize.</li>\n<li>Can balance security rigor with speed, especially in fast-moving environments.</li>\n<li>Communicate clearly across technical and non-technical partners.</li>\n<li>Have experience building or scaling security programs, either at a startup or in an embedded role.</li>\n<li>Are excited about the potential of crypto and stablecoins to power global financial infrastructure (you don’t need deep prior knowledge—just curiosity and openness to learn).</li>\n</ul>', '[\"Ruby\",\"CI/CD\",\"Product Roadmap\"]', 'SF, New York, Seattle', 0, 'Full-time', 'greenhouse', 'https://stripe.com/jobs/search?gh_jid=7573236', '7573236', '[-0.014500532,-0.008073288,0.0057630595,-0.075334616,-0.0159894,0.00037713326,-0.009050308,0.0015960357,0.018339692,0.01126811,-0.036257803,0.014395301,-0.007938695,-0.0024480335,0.11943374,0.00021916167,0.016779492,0.0056516826,0.017381921,0.0145597765,-0.00024006593,-0.01772895,0.008983816,-0.038737673,-0.031837948,-0.01375233,0.025839616,0.003482703,0.02407891,0.008236388,-0.008608146,0.010034924,0.0057462803,0.025845828,0.014276795,-0.00305108,0.03549828,-0.024845809,-0.0037922934,0.017590215,0.002527346,0.015553575,-0.0064884378,-0.023245383,0.0060956394,-0.023594948,-0.01456365,0.02312698,-0.020078035,0.029525833,-0.02567673,-0.007303345,-0.0047820522,-0.18086772,-0.01508532,0.0012213814,0.003245899,0.007950904,0.005538616,-0.0063870945,-0.0033185787,0.01742167,0.013204222,-0.029192366,0.000053549986,0.0050763916,0.010255266,0.0062972824,-0.0044404347,-0.006279773,-0.011340945,0.0060360446,-0.01346777,-0.013714993,-0.028378969,0.00716769,0.0051610833,-0.011444639,0.004219344,0.0075035836,-0.018601565,-0.006889569,-0.00660286,0.0036946407,0.006889563,-0.01345